/* La fee 2+20 est un call : fee attendue du gérant vs rendement net de l'investisseur selon le risque */
(function () {
  var svg = document.getElementById("hf-chart");
  if (!svg) return;
  function v(id){ return parseFloat(document.getElementById(id).value); }
  function setT(id,t){ var e=document.getElementById(id); if(e) e.textContent=t; }
  function al(){ return document.body.getAttribute("data-active-lang")||"fr"; }

  var A=100, MGMT=2; // fonds 100 M, management fee 2 M
  // Paramétrage : k∈[0,1]. up = 3+7k, down = 3−13k (en M). Brut moyen = 3−3k.
  function metrics(k){
    var up=3+7*k, down=3-13*k;
    var incUp=0.2*Math.max(up-MGMT,0), incDn=0.2*Math.max(down-MGMT,0);
    var incExp=0.5*(incUp+incDn);
    var fee=MGMT+incExp;
    var gross=(up+down)/2;
    var net=gross-fee;
    return {up:up, down:down, gross:gross, fee:fee, net:net};
  }

  function draw(){
    var k=v("hf-k"); setT("hf-k-o", k.toFixed(2));
    var m=metrics(k);
    setT("hf-scen", "+"+m.up.toFixed(1)+" M / "+m.down.toFixed(1)+" M");
    setT("hf-gross", m.gross.toFixed(2)+" %");
    setT("hf-fee", m.fee.toFixed(2)+" M");
    var net=document.getElementById("hf-net");
    net.textContent=m.net.toFixed(2)+" %";
    net.style.color = m.net>=0 ? "var(--teal)" : "var(--crimson)";

    var W=520,H=300,L=46,R=18,T0=18,B=34, pw=W-L-R, ph=H-T0-B;
    var ymin=-3, ymax=3; // M de fee et % de net vivent dans la même échelle ~[-3,3]
    function px(kk){ return L + kk*pw; }
    function py(val){ return T0 + (1-(val-ymin)/(ymax-ymin))*ph; }

    var g="";
    // grille zéro
    g+='<line x1="'+L+'" y1="'+py(0).toFixed(1)+'" x2="'+(L+pw)+'" y2="'+py(0).toFixed(1)+'" stroke="var(--ink-mute)" stroke-width="1" stroke-dasharray="2 4" opacity="0.5"/>';
    // courbe fee gérant (teal) et net investisseur (crimson)
    var feeP="", netP="";
    for (var i=0;i<=100;i++){ var kk=i/100, mm=metrics(kk);
      feeP+=(i===0?"M ":" L ")+px(kk).toFixed(1)+","+py(mm.fee).toFixed(1);
      netP+=(i===0?"M ":" L ")+px(kk).toFixed(1)+","+py(mm.net).toFixed(1);
    }
    g+='<path d="'+feeP+'" fill="none" stroke="var(--teal)" stroke-width="2.4"/>';
    g+='<path d="'+netP+'" fill="none" stroke="var(--crimson)" stroke-width="2.4"/>';
    // marqueur vertical au k courant
    g+='<line x1="'+px(k).toFixed(1)+'" y1="'+T0+'" x2="'+px(k).toFixed(1)+'" y2="'+(T0+ph)+'" stroke="var(--ink)" stroke-width="1.6"/>';
    g+='<circle cx="'+px(k).toFixed(1)+'" cy="'+py(m.fee).toFixed(1)+'" r="4" fill="var(--teal)"/>';
    g+='<circle cx="'+px(k).toFixed(1)+'" cy="'+py(m.net).toFixed(1)+'" r="4" fill="var(--crimson)"/>';
    // axes
    g+='<line class="axis" x1="'+L+'" y1="'+(T0+ph)+'" x2="'+(L+pw)+'" y2="'+(T0+ph)+'"/>';
    g+='<line class="axis" x1="'+L+'" y1="'+T0+'" x2="'+L+'" y2="'+(T0+ph)+'"/>';
    // libellés
    var xlab = al()==="en"?"risk level →":(al()==="nl"?"risiconiveau →":"niveau de risque →");
    var feeL = al()==="en"?"manager fee":(al()==="nl"?"beheerdersfee":"fee gérant");
    var netL = al()==="en"?"investor net":(al()==="nl"?"belegger netto":"net investisseur");
    g+='<text class="lab" x="'+(L+pw)+'" y="'+(T0+ph+16)+'" text-anchor="end">'+xlab+'</text>';
    g+='<text class="tick" x="'+(L+4)+'" y="'+(py(metrics(0.02).fee)-6).toFixed(1)+'" fill="var(--teal)">'+feeL+'</text>';
    g+='<text class="tick" x="'+(L+4)+'" y="'+(py(metrics(0.02).net)+14).toFixed(1)+'" fill="var(--crimson)">'+netL+'</text>';
    svg.innerHTML=g;
  }
  document.getElementById("hf-k").addEventListener("input", draw);
  document.querySelectorAll("[data-set-lang]").forEach(function(b){ b.addEventListener("click", function(){ setTimeout(draw,10); }); });
  document.addEventListener("DOMContentLoaded", draw);
  draw();
})();
